using System;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.Networking;using UnityEngine.Rendering;using Ashfall.Core;
namespace Ashfall.Integration.Playable.MatchZone {
 // Host time/health remain caller-owned. The visual pass draws the ORIGINAL
 // visible surface mesh, offset2mm, with the source fragment boundary equation.
