 public sealed class R24MatchZone:MonoBehaviour {
  sealed class Surface{internal MeshFilter Filter;internal MeshRenderer Renderer;internal bool Near;}
  const int MaximumSurfaces=8192;readonly List<Surface> surfaces=new List<Surface>();readonly HashSet<MeshFilter> ids=new HashSet<MeshFilter>();readonly List<Transform> roots=new List<Transform>();MaterialPropertyBlock properties;Transform map,actor;Camera head;Vector3 godotOrigin;Material surfaceMaterial,dangerMaterial;Mesh quad;AudioSource edgeAudio,outsideAudio;AudioClip loop;Func<R24ZoneDamage,bool> damage;R24ZonePlan plan;double shownTime;bool ready,viewEnabled,disposed;float collectLeft,cullLeft,sfx=1,bottom=-300,ceiling=1500;string actorId="player";
  public R24MatchZoneHost Host{get;private set;}public bool AudioReady{get{return loop!=null;}}public string AudioFailure{get;private set;}public bool Outside{get;private set;}public bool PlayerOutside{get;private set;}public float EdgeDistance{get;private set;}public int SurfaceCount{get{return surfaces.Count;}}public int OmittedSurfaceCount{get;private set;}public int LastDrawCalls{get;private set;}public R24ZoneDamage LastDamageRequest{get;private set;}public bool LastDamageAccepted{get;private set;}public bool Visible{get{return viewEnabled&&plan!=null;}}
  public void Initialize(Transform actualMapRoot,Transform actualActorRoot,Camera actualHead,Func<R24ZoneDamage,bool> applyActualHealthDamage,Vector3 sourceGodotOrigin){if(ready||actualMapRoot==null||actualActorRoot==null||actualHead==null)throw new ArgumentException("Actual map/player/head required");properties=new MaterialPropertyBlock();map=actualMapRoot;actor=actualActorRoot;head=actualHead;damage=applyActualHealthDamage;godotOrigin=sourceGodotOrigin;surfaceMaterial=new Material(Resources.Load<Shader>("R24ZoneSurface"));dangerMaterial=new Material(Resources.Load<Shader>("R24ZoneDanger"));quad=new Mesh();quad.name="Actual source danger QuadMesh";quad.vertices=new[]{new Vector3(-.5f,-.5f,0),new Vector3(.5f,-.5f,0),new Vector3(.5f,.5f,0),new Vector3(-.5f,.5f,0)};quad.triangles=new[]{0,2,1,0,3,2};quad.RecalculateBounds();edgeAudio=Voice("Original spatial zone edge loop",true);outsideAudio=Voice("Original outside zone loop",false);roots.Add(map);ready=true;RefreshSurfaces();StartCoroutine(LoadAudio());}
  public void SetMap(Transform actualMapRoot,Vector3 sourceGodotOrigin){if(!ready||actualMapRoot==null)throw new ArgumentException("Actual map root required");Suspend();map=actualMapRoot;godotOrigin=sourceGodotOrigin;surfaces.Clear();ids.Clear();roots.Clear();roots.Add(map);collectLeft=cullLeft=0;OmittedSurfaceCount=0;RefreshSurfaces();}
  public void ClearRound(){Host=null;plan=null;LastDamageRequest=null;LastDamageAccepted=false;PlayerOutside=false;Suspend();}
  public void BindHost(R24MatchZoneHost actualHost,string actualActorId="player"){if(actualHost==null||string.IsNullOrEmpty(actualActorId))throw new ArgumentException();Host=actualHost;actorId=actualActorId;plan=Host.State;LastDamageRequest=null;LastDamageAccepted=false;}
  // Invoke ONCE per actual host frame. For multi-actor listen hosting, host
  // composition can Tick Host directly, RequestDamage for each real actor, then
  // call Present here; clients only call Present with the authoritative plan.
  public void Step(double actualHostTime,double actualDelta,bool matchActive,bool renderEnabled,bool loaded,bool alive,double protectionUntil){if(!ready||Host==null)return;LastDamageRequest=null;LastDamageAccepted=false;bool damageTick=Host.Tick(actualHostTime,actualDelta,matchActive);plan=Host.State;PlayerOutside=plan!=null&&!plan.Current(actualHostTime).Contains(Local(actor.position).X,Local(actor.position).Z);R24ZoneDamage request;if(damageTick&&Host.RequestDamage(actorId,Local(actor.position),loaded,alive,protectionUntil,out request)){LastDamageRequest=request;if(damage!=null)LastDamageAccepted=damage(request);}Present(plan,actualHostTime,(float)actualDelta,matchActive&&renderEnabled);}
  // Listen-host composition: request damage for another real actor from the SAME
  // host owner/tick Step just advanced. Same map frame as the local actor; the
  // owner's per-tick actor set still allows one request per actor per damage tick.
  public bool TryRequestActorDamage(string actualActor,Vector3 actualWorldRoot,double protectionUntil,out R24ZoneDamage request){request=null;if(!ready||disposed||Host==null||string.IsNullOrEmpty(actualActor)||actualActor==actorId)return false;var local=Local(actualWorldRoot);return local.IsFinite&&Host.RequestDamage(actualActor,local,true,true,protectionUntil,out request);}
  public void Present(R24ZonePlan authoritativePlan,double actualTime,float visualDelta,bool enabled){if(!ready||disposed)return;if(!R24ZoneMath.Finite(actualTime)||float.IsNaN(visualDelta)||float.IsInfinity(visualDelta)||visualDelta<0)throw new ArgumentOutOfRangeException();plan=authoritativePlan;shownTime=actualTime;viewEnabled=enabled&&plan!=null;if(!Visible){StopAudio();Outside=false;EdgeDistance=float.PositiveInfinity;return;}collectLeft-=visualDelta;if(collectLeft<=0){collectLeft=1;RefreshSurfaces();}cullLeft-=visualDelta;var current=plan.Current(shownTime);if(cullLeft<=0){cullLeft=.1f;Cull(current,plan.Next);}properties.SetMatrix("_WorldToGodotMap",Matrix4x4.Scale(new Vector3(1,1,-1))*map.worldToLocalMatrix);properties.SetVector("_CurrentSquare",Rect(current));properties.SetVector("_NextSquare",Rect(plan.Next));properties.SetVector("_GodotOrigin",godotOrigin);properties.SetFloat("_SourceTime",Time.time);UpdateAudio(current);}
  public void ConfigureSourceHeight(bool sourceHasArchiveMeta,float solidMinY,float solidMaxY,float launchCeilingGodotWorld){bottom=sourceHasArchiveMeta?solidMinY-30:-300;ceiling=sourceHasArchiveMeta?Mathf.Max(600,solidMaxY+400):1500;ceiling=Mathf.Max(ceiling,launchCeilingGodotWorld+30-godotOrigin.y);}
  public void RegisterSurfaceRoot(Transform actualRoot){if(actualRoot!=null&&!roots.Contains(actualRoot)){roots.Add(actualRoot);RefreshSurfaces();}}
  public void RegisterSurface(MeshFilter mesh,MeshRenderer renderer){if(mesh==null||renderer==null||mesh.sharedMesh==null||ids.Contains(mesh))return;if(surfaces.Count>=MaximumSurfaces){OmittedSurfaceCount++;return;}ids.Add(mesh);surfaces.Add(new Surface{Filter=mesh,Renderer=renderer});cullLeft=0;}
  public void RefreshSurfaces(){if(!ready)return;for(int i=surfaces.Count-1;i>=0;i--)if(surfaces[i].Filter==null||surfaces[i].Renderer==null){ids.Remove(surfaces[i].Filter);surfaces.RemoveAt(i);}for(int r=roots.Count-1;r>=0;r--){var root=roots[r];if(root==null){roots.RemoveAt(r);continue;}foreach(var mesh in root.GetComponentsInChildren<MeshFilter>(true))RegisterSurface(mesh,mesh.GetComponent<MeshRenderer>());}}
  void Cull(R24ZoneSquare current,R24ZoneSquare next){foreach(var s in surfaces){if(s.Filter==null||s.Renderer==null){s.Near=false;continue;}Bounds bounds=s.Renderer.bounds;double minX=double.PositiveInfinity,minZ=minX,maxX=double.NegativeInfinity,maxZ=maxX;for(int n=0;n<8;n++){Vector3 p=bounds.center+Vector3.Scale(bounds.extents,new Vector3((n&1)==0?-1:1,(n&2)==0?-1:1,(n&4)==0?-1:1));var local=Local(p);minX=Math.Min(minX,local.X);maxX=Math.Max(maxX,local.X);minZ=Math.Min(minZ,local.Z);maxZ=Math.Max(maxZ,local.Z);}s.Near=NearBoundary(minX,minZ,maxX,maxZ,current)||NearBoundary(minX,minZ,maxX,maxZ,next);}}
  public static bool NearBoundary(double minX,double minZ,double maxX,double maxZ,R24ZoneSquare zone){bool overlap=maxX>=zone.X-3&&minX<=zone.MaxX+3&&maxZ>=zone.Z-3&&minZ<=zone.MaxZ+3;bool enclosed=zone.Size>6&&minX>=zone.X+3&&maxX<=zone.MaxX-3&&minZ>=zone.Z+3&&maxZ<=zone.MaxZ-3;return overlap&&!enclosed;}
  void LateUpdate(){LastDrawCalls=0;if(!Visible||head==null||map==null)return;foreach(var s in surfaces){var renderer=s.Renderer;var filter=s.Filter;if(!s.Near||filter==null||renderer==null||!renderer.enabled||!renderer.gameObject.activeInHierarchy||renderer.shadowCastingMode==ShadowCastingMode.ShadowsOnly||(head.cullingMask&(1<<renderer.gameObject.layer))==0)continue;var mesh=filter.sharedMesh;if(mesh==null)continue;for(int sub=0;sub<mesh.subMeshCount;sub++){Graphics.DrawMesh(mesh,filter.transform.localToWorldMatrix,surfaceMaterial,renderer.gameObject.layer,head,sub,properties,ShadowCastingMode.Off,false,null,false);LastDrawCalls++;}}DrawDanger(plan.Current(shownTime));}
  void DrawDanger(R24ZoneSquare square){float x=(float)square.X,z=(float)square.Z,size=(float)square.Size,y=(bottom+ceiling)*.5f,height=ceiling-bottom;for(int n=0;n<4;n++){Vector3 at=n==0?new Vector3(x+size*.5f,y,-z):n==1?new Vector3(x+size,y,-(z+size*.5f)):n==2?new Vector3(x+size*.5f,y,-(z+size)):new Vector3(x,y,-(z+size*.5f));Matrix4x4 pose=map.localToWorldMatrix*Matrix4x4.TRS(at,Quaternion.Euler(0,n%2==1?90:0,0),new Vector3(size,height,1));Graphics.DrawMesh(quad,pose,dangerMaterial,0,head,0,properties,ShadowCastingMode.Off,false,null,false);LastDrawCalls++;}}
  Float3 Local(Vector3 world){var p=map.InverseTransformPoint(world);return new Float3(p.x,p.y,-p.z);}static Vector4 Rect(R24ZoneSquare r){return new Vector4((float)r.X,(float)r.Z,(float)r.MaxX,(float)r.MaxZ);}
  AudioSource Voice(string label,bool spatial){var go=new GameObject(label);go.transform.SetParent(transform,false);var s=go.AddComponent<AudioSource>();s.playOnAwake=false;s.loop=true;s.spatialBlend=spatial?1:0;s.dopplerLevel=0;s.rolloffMode=AudioRolloffMode.Custom;s.SetCustomCurve(AudioSourceCurveType.CustomRolloff,AnimationCurve.Linear(0,1,1,1));s.minDistance=1;s.maxDistance=5;return s;}
  IEnumerator LoadAudio(){string path=Application.streamingAssetsPath+"/PlayableR23/MatchZone/danger_zone_hum.wav";string url=path.Contains("://")?path:new Uri(path).AbsoluteUri;using(var req=UnityWebRequestMultimedia.GetAudioClip(url,AudioType.WAV)){yield return req.SendWebRequest();if(req.result!=UnityWebRequest.Result.Success){AudioFailure=req.error;yield break;}loop=DownloadHandlerAudioClip.GetContent(req);edgeAudio.clip=outsideAudio.clip=loop;}}
  void UpdateAudio(R24ZoneSquare square){var local=Local(head.transform.position);double ex,ez;R24ZoneMath.NearestEdge(square,local.X,local.Z,out ex,out ez);EdgeDistance=(float)Math.Sqrt((ex-local.X)*(ex-local.X)+(ez-local.Z)*(ez-local.Z));Outside=!square.Contains(local.X,local.Z);Vector3 edge=map.TransformPoint(new Vector3((float)ex,local.Y,(float)-ez));edge.y=head.transform.position.y;edgeAudio.transform.position=edge;var root=Local(actor.position);bool rootOutside=!square.Contains(root.X,root.Z);var levels=new R24ZoneAudioLevels(EdgeDistance,Outside,rootOutside,sfx);edgeAudio.volume=levels.Edge;outsideAudio.volume=levels.Danger;if(loop==null)return;if(levels.Edge>0){if(!edgeAudio.isPlaying)edgeAudio.Play();}else edgeAudio.Stop();if(levels.Danger>0){if(!outsideAudio.isPlaying)outsideAudio.Play();}else outsideAudio.Stop();}
  public void SetSfxVolume(float value){if(float.IsNaN(value)||float.IsInfinity(value))throw new ArgumentOutOfRangeException();sfx=Mathf.Clamp01(value);if(Visible)UpdateAudio(plan.Current(shownTime));}public void Suspend(){viewEnabled=false;Outside=false;EdgeDistance=float.PositiveInfinity;StopAudio();}void StopAudio(){if(edgeAudio!=null)edgeAudio.Stop();if(outsideAudio!=null)outsideAudio.Stop();}// Root passes actual OpenXR render/focus availability to Present; mirror-window focus must not permanently mute the zone.
  void OnApplicationPause(bool paused){if(paused)StopAudio();}void OnDisable(){Suspend();}void OnDestroy(){disposed=true;StopAudio();StopAllCoroutines();if(edgeAudio!=null)Destroy(edgeAudio.gameObject);if(outsideAudio!=null)Destroy(outsideAudio.gameObject);if(loop!=null)Destroy(loop);if(surfaceMaterial!=null)Destroy(surfaceMaterial);if(dangerMaterial!=null)Destroy(dangerMaterial);if(quad!=null)Destroy(quad);surfaces.Clear();ids.Clear();roots.Clear();}
 }
}
